// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');

// Load elegant sans-serif font at module level
const { fontFamily: montserratFamily } = loadMontserrat();



export type ExcellenceChartProps = Record<string, any>;

interface IconProps {
  stroke: string;
  sw: number;
  fill?: string;
}

// ---------------------------------------------------------------------------
// SVG ICONS
// ---------------------------------------------------------------------------
const FragranceIcon = ({ stroke, sw, fill }: IconProps) => (
  <g stroke={stroke} strokeWidth={sw} fill="none" strokeLinejoin="round">
    <rect x="-22" y="-12" width="44" height="38" rx="6" fill={fill} />
    <rect x="-10" y="-22" width="20" height="10" fill={fill} />
    <circle cx="0" cy="-30" r="8" fill={stroke} />
    <line x1="0" y1="-12" x2="0" y2="26" strokeOpacity={0.4} />
  </g>
);

const FoundationIcon = ({ stroke, sw, fill }: IconProps) => (
  <g stroke={stroke} strokeWidth={sw} fill="none" strokeLinejoin="round">
    <rect x="-16" y="-12" width="32" height="42" rx="4" fill={fill} />
    <rect x="-10" y="-22" width="20" height="10" fill={fill} />
    {/* Pump mechanism */}
    <path d="M-4,-22 L-4,-35 L12,-35 L12,-28 L4,-28 L4,-22 Z" fill={stroke} />
  </g>
);

const LipstickIcon = ({ stroke, sw, fill }: IconProps) => (
  <g stroke={stroke} strokeWidth={sw} fill="none" strokeLinejoin="round">
    <rect x="-12" y="2" width="24" height="28" rx="2" fill={fill} />
    <rect x="-8" y="-12" width="16" height="14" fill={fill} />
    <path d="M-8,-12 L-8,-26 L8,-32 L8,-12 Z" fill={stroke} />
  </g>
);

const EyeshadowIcon = ({ stroke, sw, fill }: IconProps) => (
  <g stroke={stroke} strokeWidth={sw} fill="none" strokeLinejoin="round">
    {/* Lid angled up */}
    <path d="M-24,-16 L-10,-30 L38,-30 L24,-16 Z" />
    {/* Base */}
    <rect x="-24" y="-16" width="48" height="32" rx="4" fill={fill} />
    {/* Pans */}
    <rect x="-18" y="-10" width="14" height="8" rx="1" />
    <rect x="4" y="-10" width="14" height="8" rx="1" />
    <rect x="-18" y="2" width="14" height="8" rx="1" />
    <rect x="4" y="2" width="14" height="8" rx="1" />
  </g>
);

const MascaraIcon = ({ stroke, sw, fill }: IconProps) => (
  <g stroke={stroke} strokeWidth={sw} fill="none" strokeLinejoin="round" strokeLinecap="round">
    {/* Tube */}
    <rect x="-7" y="-2" width="14" height="34" rx="3" fill={fill} />
    {/* Cap */}
    <rect x="-7" y="-28" width="14" height="20" rx="2" fill={stroke} />
    {/* Ribs drawn onto the solid cap */}
    <line x1="-12" y1="-23" x2="12" y2="-23" stroke={fill} strokeWidth={sw * 0.6} />
    <line x1="-12" y1="-17" x2="12" y2="-17" stroke={fill} strokeWidth={sw * 0.6} />
  </g>
);

const ExcellenceChart: React.FC<ExcellenceChartProps> = ({
  backgroundColor = "#F5F3ED",
  transparentBackground = false,
  durationInSeconds = 10,
  textColor = "#1A1A1A",
  lineColor = "#1A1A1A",
  bubbleColor = "#FFFFFF",
  fragranceLabel = "FRAGRANCE",
  foundationLabel = "FOUNDATION",
  lipstickLabel = "LIPSTICK",
  eyeshadowLabel = "EYESHADOW",
  mascaraLabel = "MASCARA",
  routineLabel = "COMPLETE REGIMEN",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // ---------------------------------------------------------------------------
  // TIMELINE & COORDINATES
  // ---------------------------------------------------------------------------
  const totalFrames = durationInSeconds * fps;
  
  const cx = width / 2;
  const cy = height / 2;
  const baseR = width * 0.045;
  const orbitR = width * 0.18;
  const iconScale = width * 0.0009;

  // Angles for the 4 outer nodes forming an X around the center
  const angles = [-Math.PI / 4, Math.PI / 4, 3 * Math.PI / 4, -3 * Math.PI / 4];
  const outerIcons = [FoundationIcon, LipstickIcon, EyeshadowIcon, MascaraIcon];
  const outerLabelsText = [foundationLabel, lipstickLabel, eyeshadowLabel, mascaraLabel];

  // Timing windows
  const centerEntryFrames = [totalFrames * 0.02, totalFrames * 0.08];

  const intervals = [
    { start: 0.10, end: 0.15 }, // Line 0
    { start: 0.15, end: 0.20 }, // Node 0 (Foundation)
    { start: 0.22, end: 0.27 }, // Line 1
    { start: 0.27, end: 0.32 }, // Node 1 (Lipstick)
    { start: 0.34, end: 0.39 }, // Line 2
    { start: 0.39, end: 0.44 }, // Node 2 (Eyeshadow)
    { start: 0.46, end: 0.51 }, // Line 3
    { start: 0.51, end: 0.56 }, // Node 3 (Mascara)
  ];

  const lineDraws = intervals.filter((_, i) => i % 2 === 0).map(inv => [totalFrames * inv.start, totalFrames * inv.end]);
  const nodeScales = intervals.filter((_, i) => i % 2 !== 0).map(inv => [totalFrames * inv.start, totalFrames * inv.end]);

  const mergeFrames = [totalFrames * 0.65, totalFrames * 0.75];
  const morphFrames = [totalFrames * 0.75, totalFrames * 0.85];

  // ---------------------------------------------------------------------------
  // ANIMATION PROGRESS CALCS
  // ---------------------------------------------------------------------------
  const centerScale = interpolate(frame, centerEntryFrames, [0, 1], { easing: Easing.out(Easing.back(1.5)), extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const mergeProgress = interpolate(frame, mergeFrames, [0, 1], { easing: Easing.inOut(Easing.cubic), extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const morphProgress = interpolate(frame, morphFrames, [0, 1], { easing: Easing.inOut(Easing.quad), extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const finalPop = interpolate(
    frame, 
    [morphFrames[1], morphFrames[1] + totalFrames * 0.05, morphFrames[1] + totalFrames * 0.1], 
    [1, 1.05, 1], 
    { easing: Easing.inOut(Easing.quad), extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Outer node clustering during merge
  const currentOrbitDist = interpolate(mergeProgress, [0, 1], [orbitR, 0], { extrapolateRight: "clamp" });
  const outerNodeOpacity = interpolate(mergeProgress, [0.5, 1], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  
  // Available space for drawing lines
  const currentLineSpace = Math.max(0, currentOrbitDist - 2 * baseR);

  // Morph expanding center bubble into a pill
  const cw = interpolate(morphProgress, [0, 1], [baseR * 2, width * 0.35]);
  const ch = interpolate(morphProgress, [0, 1], [baseR * 2, width * 0.12]);
  const crx = interpolate(morphProgress, [0, 1], [baseR, width * 0.06]);

  const fragOpacity = interpolate(morphProgress, [0.2, 0.6], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const routineOpacity = interpolate(morphProgress, [0.4, 0.8], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // Label styles
  const labelStyle: React.CSSProperties = {
    fontFamily: montserratFamily,
    fontSize: width * 0.015,
    color: textColor,
    fontWeight: 600,
    letterSpacing: "0.1em",
    textTransform: "uppercase",
    transition: "none",
  };
  const centerLabelY = cy + ch / 2 + width * 0.025;
  const totalCenterScale = centerScale * finalPop;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* 1. SVG DRAWING LAYER */}
      <svg style={{ position: "absolute", top: 0, left: 0, width, height, overflow: "visible", pointerEvents: "none" }}>
        
        {/* Connection Lines */}
        {angles.map((a, i) => {
          const rawDraw = interpolate(frame, lineDraws[i], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
          const drawLength = rawDraw * currentLineSpace;
          if (drawLength <= 0) return null;
          return (
            <line 
              key={`line-${i}`}
              x1={cx + Math.cos(a) * baseR}
              y1={cy + Math.sin(a) * baseR}
              x2={cx + Math.cos(a) * (baseR + drawLength)}
              y2={cy + Math.sin(a) * (baseR + drawLength)}
              stroke={lineColor}
              strokeWidth={4}
              strokeLinecap="round"
            />
          );
        })}

        {/* Center Bubble / Pill */}
        <rect
          x={cx - cw / 2}
          y={cy - ch / 2}
          width={cw}
          height={ch}
          rx={crx}
          fill={bubbleColor}
          stroke={lineColor}
          strokeWidth={4}
          style={{ transform: `scale(${totalCenterScale})`, transformOrigin: `${cx}px ${cy}px` }}
        />

        {/* Outer Bubbles & Icons */}
        {angles.map((a, i) => {
          const scale = interpolate(frame, nodeScales[i], [0, 1], { easing: Easing.out(Easing.back(1.5)), extrapolateLeft: "clamp", extrapolateRight: "clamp" });
          if (scale === 0) return null;
          
          const nx = cx + Math.cos(a) * currentOrbitDist;
          const ny = cy + Math.sin(a) * currentOrbitDist;
          const IconComponent = outerIcons[i];
          
          return (
            <g key={`outer-${i}`} opacity={outerNodeOpacity} style={{ transform: `scale(${scale})`, transformOrigin: `${nx}px ${ny}px` }}>
              <circle cx={nx} cy={ny} r={baseR} fill={bubbleColor} stroke={lineColor} strokeWidth={4} />
              <g transform={`translate(${nx}, ${ny}) scale(${iconScale})`}>
                <IconComponent stroke={lineColor} sw={4 / iconScale} fill={bubbleColor} />
              </g>
            </g>
          );
        })}

        {/* Center Icons (Crossfading Morph) */}
        <g style={{ transform: `scale(${totalCenterScale})`, transformOrigin: `${cx}px ${cy}px` }}>
          {/* Initial Single Fragrance Bottle */}
          <g opacity={fragOpacity} transform={`translate(${cx}, ${cy}) scale(${iconScale})`}>
            <FragranceIcon stroke={lineColor} sw={4 / iconScale} fill={bubbleColor} />
          </g>
          
          {/* Final Complete Regimen Lineup */}
          <g opacity={routineOpacity} transform={`translate(${cx}, ${cy}) scale(${iconScale * 0.8})`}>
            <g transform="translate(-70, 5)"><EyeshadowIcon stroke={lineColor} sw={4 / (iconScale * 0.8)} fill={bubbleColor} /></g>
            <g transform="translate(-30, 0)"><FoundationIcon stroke={lineColor} sw={4 / (iconScale * 0.8)} fill={bubbleColor} /></g>
            <g transform="translate(15, -5)"><FragranceIcon stroke={lineColor} sw={4 / (iconScale * 0.8)} fill={bubbleColor} /></g>
            <g transform="translate(55, 5)"><LipstickIcon stroke={lineColor} sw={4 / (iconScale * 0.8)} fill={bubbleColor} /></g>
            <g transform="translate(90, 0)"><MascaraIcon stroke={lineColor} sw={4 / (iconScale * 0.8)} fill={bubbleColor} /></g>
          </g>
        </g>
      </svg>

      {/* 2. HTML TYPOGRAPHY LAYER */}
      {/* Initial Center Label */}
      <div style={{ ...labelStyle, position: "absolute", left: cx, top: centerLabelY, transform: `translate(-50%, 0) scale(${finalPop})`, opacity: (1 - morphProgress) * centerScale }}>
        {fragranceLabel}
      </div>
      
      {/* Final Center Label */}
      <div style={{ ...labelStyle, position: "absolute", left: cx, top: centerLabelY, transform: `translate(-50%, 0) scale(${finalPop})`, opacity: morphProgress }}>
        {routineLabel}
      </div>

      {/* Outer Nodes Labels */}
      {angles.map((a, i) => {
        const scale = interpolate(frame, nodeScales[i], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
        if (scale === 0) return null;
        
        const nx = cx + Math.cos(a) * currentOrbitDist;
        const ny = cy + Math.sin(a) * currentOrbitDist;
        
        return (
          <div key={`label-${i}`} style={{ ...labelStyle, position: "absolute", left: nx, top: ny + baseR + width * 0.025, transform: "translate(-50%, 0)", opacity: scale * outerNodeOpacity }}>
            {outerLabelsText[i]}
          </div>
        );
      })}
      
    </AbsoluteFill>
  );
};

export default ExcellenceChart;